const select=document.querySelector('#design-select'),frame=document.querySelector('iframe'),stage=document.querySelector('.review-stage');const names={1:'Clear & Confident',2:'Editorial Academy',3:'Course Navigator',4:'Community Focus'};
function show(value,replace=false){const option=names[value]?value:'1';select.value=option;frame.src='option-'+option+'.html';frame.title='AIFL — '+names[option];document.title='AIFL · '+names[option];document.querySelector('#standalone').href='option-'+option+'.html';document.querySelector('#choose-link').href='designs.html?choose='+option+'#your-choice';const url=new URL(location.href);url.searchParams.set('option',option);history[replace?'replaceState':'pushState']({},'',url)}
show(new URLSearchParams(location.search).get('option'),true);select.addEventListener('change',()=>show(select.value));window.addEventListener('popstate',()=>show(new URLSearchParams(location.search).get('option'),true));document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{stage.classList.toggle('mobile',button.dataset.view==='mobile');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)))}));
frame.addEventListener('load',()=>{try{frame.contentDocument.querySelectorAll('a[href^="https://"],a[href^="http://"]').forEach(a=>{a.target='_blank';a.rel='noopener'})}catch{}});
